Find Insuree By CHF ID.code:
// Find an insuree (Patient) by insurance number (CHF ID).
getFHIR('Patient/', {
  identifier: $.data.insuranceNumber, // e.g. '070707070'
});

List Insurees Page By Page.code:
// List insurees, 50 at a time.
getFHIR('Patient/', {
  _count: 50, // page size
  'page-offset': $.data.page || 1, // which page to fetch
});

Find Claims For Insuree.code:
// List claims for one insuree.
getFHIR('Claim/', {
  patient: $.data.insureeUuid, // the Patient's UUID
  _count: 100,
});

Check Insuree Coverage.code:
// Check which policies (Coverage) were active on a date.
getFHIR('Coverage/', {
  refDate: $.data.serviceDate, // e.g. '2026-10-15'
  _count: 100,
});

List Policy Holders.code:
// List policy holders (Organization resources).
getFHIR('Organization/', {
  resourceType: 'ph', // policy holders
  _count: 100,
});
